with base as (select id, city, date_sub(opened_date, 75) opened_date_minus_75d from stores where opened_date >= date '2024-02-04') select date_trunc('week', opened_date_minus_75d) as week_start, sort_array(collect_set(city)) as city_list, count(*) as num_rows, size(collect_set(city)) as num_cities, count(distinct id) as distinct_ids, grouping(date_trunc('week', opened_date_minus_75d)) as grouping_level from base group by rollup (date_trunc('week', opened_date_minus_75d)) order by num_cities desc
